fn array_sum(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Ensure the two input arrays have the same length
    assert_eq!(a.len(), b.len(), "Input arrays must have the same length");

    // Zip element-wise and sum, then collect into a new Vec<i32>
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x + y)
     .collect()
}

fn main() {
    let v1 = vec![1, 2, 3, 4];
    let v2 = vec![10, 20, 30, 40];
    let summed = array_sum(v1, v2);
    assert_eq!(summed, vec![11, 22, 33, 44]);
    println!("Element-wise sum: {:?}", summed);
}